use std::env; use crate::adapters::translator_trait::TranslatorAdapter; use crate::adapters::types::{AdapterError,ProviderKind,TranslateRequest,TranslateResponse};
#[derive(Default)] pub struct MockTranslator;
impl TranslatorAdapter for MockTranslator { fn provider_kind(&self)->ProviderKind{ProviderKind::Mock} fn translate_once(&self, request:&TranslateRequest)->Result<TranslateResponse,AdapterError>{ let mode=env::var("MOCK_TRANSLATE_MODE").unwrap_or_else(|_|"zh_demo".to_string()); let translated_text=match mode.as_str(){ "identity"=>request.text.clone(), "zh_demo"=>match request.text.as_str(){ "確認"=>"确认".to_string(), "高速"=>"高速_译".to_string(), _=>format!("ZH<{}>",request.text), }, _=>format!("ZH<{}>",request.text), }; Ok(TranslateResponse{request_id:request.request_id.clone(), provider:ProviderKind::Mock, translated_text, detected_source_lang:None, raw_meta:None}) } }
